1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const TYPE_THRESHOLD = 3;
7	
8	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
9	
10	const countDistinctTypes = (army: Card[]): number =>
11	  new Set(army.map((card) => card.monster)).size;
12	
13	export const scoreArmy = (army: Card[]): number => {
14	  const typeCount = countDistinctTypes(army);
15	  const pointsPerSphinx =
16	    typeCount > TYPE_THRESHOLD ? 2 * (typeCount - TYPE_THRESHOLD) : 1;
17	  return army.filter(isSphinx).length * pointsPerSphinx;
18	};
